mapper.select:
SELECT id, file_name, insur_type, insur_type_name, data_date, row_count, status, create_time, update_time
FROM (
    SELECT f.*, ROWNUM AS rn
    FROM (
        SELECT id, file_name, insur_type, insur_type_name, data_date, row_count, status, create_time, update_time
        FROM tr_mi_recon_file


                AND insur_type = #{insurType}


                AND data_date = TO_DATE(#{dataDate}, 'yyyy-mm-dd')


        ORDER BY insur_type ASC, data_date DESC, create_time DESC, id DESC
    ) f
    WHERE ROWNUM <= #{endRow}
)
WHERE rn >= #{startRow}

SELECT COUNT(*) FROM tr_mi_recon_file
AND insur_type = #{insurType}
AND data_date = TO_DATE(#{dataDate}, 'yyyy-mm-dd')

SELECT id, file_name, insur_type, insur_type_name, data_date, row_count, status, create_time, update_time
FROM tr_mi_recon_file
WHERE id = #{id}

mapper.update:
UPDATE tr_mi_recon_file
SET status = #{status}, update_time = SYSDATE
WHERE id = #{id}

UPDATE tr_mi_recon_file
SET insur_type = #{insurType}, insur_type_name = #{insurTypeName}, update_time = SYSDATE
WHERE id = #{id}

UPDATE tr_mi_recon_detail
SET insur_type = #{insurType}, insur_type_name = #{insurTypeName}
WHERE file_id = #{id}

mapper.select:
SELECT TO_CHAR(settle_date, 'yyyy-mm-dd') AS settle_date
FROM tr_mi_recon_detail
WHERE file_id = #{fileId}

mapper.update:
UPDATE tr_mi_recon_file f
SET f.status = '0', f.update_time = SYSDATE
WHERE f.insur_type = #{insurType}
  AND f.status = '1'
  AND f.id != #{excludeId}
  AND EXISTS (
      SELECT 1 FROM tr_mi_recon_detail d
      WHERE d.file_id = f.id
        AND d.insur_type = #{insurType}
        AND d.settle_date IN

          TO_DATE(#{d}, 'yyyy-mm-dd')

  )

