SELECT COUNT(*)
FROM tr_mi_recon_file f
WHERE f.insur_type = #{insurType}
  AND f.status = '1'
  AND f.id != #{excludeId}
  AND EXISTS (
      SELECT 1 FROM tr_mi_recon_detail d
      WHERE d.file_id = f.id
        AND d.insur_type = #{insurType}
        AND d.settle_date IN

          TO_DATE(#{d}, 'yyyy-mm-dd')

